-- REQ-FEAT-019 (2026-10-18) - Student Import Phases.
--
-- User maintains an offline Excel workbook ("WEBSITE FD REPLACEMENT.xlsx")
-- with one sheet per "phase" - a batch of students added or had their full
-- details replaced together, submitted as a unit to the state (UDISE) and
-- national (PEN) student registries. Wants this generated by the website
-- automatically going forward, downloadable by phase, in the same column
-- layout as that offline template (same field set as the admin panel's
-- existing Import Students / Replace Full Details tools' IMPORT_FIELDS).
--
-- Clarified before building: a phase is a LOCKED, PERMANENT historical
-- record - what was actually submitted for UDISE/PEN at that moment - not
-- a live view that follows the student's current data if they're edited
-- again later. Hence `snapshot` is a point-in-time JSONB copy of the
-- fields, not a join back to `students`/`student_enrollments`.
--
-- Scope: one phase per "write batch" - a single Add Student / Edit Student
-- save is its own 1-student phase; a bulk Import Students / Replace Full
-- Details / Basic Details Import run is one phase covering every row in
-- that run. Entirely automatic - no manual "start/close phase" step.
--
-- Same posture as other admin-only tables (student_daily_log,
-- student_risk_flags): RLS enabled, `authenticated` + `is_admin_user()`.
-- No mobile access at all - this is an admin-panel-only feature.

CREATE TABLE IF NOT EXISTS public.student_import_phases (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  phase_number  SERIAL UNIQUE,
  phase_type    TEXT NOT NULL CHECK (phase_type IN ('Added','Replaced')),
  source        TEXT NOT NULL,
  student_count INT NOT NULL DEFAULT 0,
  created_by    UUID REFERENCES public.admin_users(id) ON DELETE SET NULL,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- One row per student touched in that phase. student_id is kept nullable +
-- ON DELETE SET NULL (not CASCADE) so a permanently-deleted student doesn't
-- silently erase the historical submission record - the snapshot survives
-- even if the live student row is later removed.
CREATE TABLE IF NOT EXISTS public.student_import_phase_entries (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  phase_id      UUID NOT NULL REFERENCES public.student_import_phases(id) ON DELETE CASCADE,
  student_id    UUID REFERENCES public.students(id) ON DELETE SET NULL,
  enrollment_no TEXT,
  snapshot      JSONB NOT NULL,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_phase_entries_phase   ON public.student_import_phase_entries(phase_id);
CREATE INDEX IF NOT EXISTS idx_phase_entries_student ON public.student_import_phase_entries(student_id);

ALTER TABLE public.student_import_phases        ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.student_import_phase_entries ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "admin manage student_import_phases" ON public.student_import_phases;
CREATE POLICY "admin manage student_import_phases" ON public.student_import_phases
  FOR ALL TO authenticated USING (public.is_admin_user()) WITH CHECK (public.is_admin_user());
DROP POLICY IF EXISTS "admin manage student_import_phase_entries" ON public.student_import_phase_entries;
CREATE POLICY "admin manage student_import_phase_entries" ON public.student_import_phase_entries
  FOR ALL TO authenticated USING (public.is_admin_user()) WITH CHECK (public.is_admin_user());
